FILE = "the-drop-30-oct-2026.html"
TITLE = "The Drop: Bensoul's Flight 420, Toxic Lyrikali, Dominic Fike and more"
TAG = "The Drop"
H1 = "The Drop: nine new releases"
DEK = "Bensoul's Flight 420 takes off, Toxic Lyrikali lands an EP, and Dominic Fike, Sampa the Great and Blxckie all drop albums. Everything worth pressing play on from 29–30 October."
META = "The Drop · 29–30 October 2026 · 6 min read"
LEAD = ("img/drop1-hero.jpg", "Bensoul's Flight 420 artwork", "Sudah Nation", "Artwork")

BODY = [
("p", "Kenya came through this week. Bensoul's new album and a new EP from Toxic Lyrikali lead a busy Friday that also brings a third album from Dominic Fike, Sampa the Great's return to Zamrock and Blxckie's second album. Here's everything that dropped, and where to start."),
("list", "posters", [
 ("01", "img/drop1-bensoul.jpg", "Flight 420", "Bensoul", "Album · out Friday 30 October", [
   "Bensoul's new album is 13 tracks long and leans into a reggae-inspired sound, blended with the Afrosoul he's known for. He previewed it for fans at a listening session in Nairobi earlier this week.",
   "The guest list runs deep: Scar Mkadinali on “NYR”, Spyro on “A Glass of Wine”, Watendawili on “Naenjoy”, Kasiva Mutua on “Bossa Nova”, Ywaya Tajiri on “Mariwana”, Mike Kayihura on “Nobody Wins, Nobody Loses”, Hornsphere on “RobinHood” and Savara on “Tears of Joy”. It closes on “Thank You”."]),
 ("02", "img/drop1-toxic.jpg", "Abundance", "Toxic Lyrikali", "EP · out Thursday 29 October", [
   "Toxic Lyrikali beat the Friday rush with a short, sharp project. <em>Abundance</em> is five tracks and about 15 minutes long: “Most Wanted”, “Mafia Boss”, “Time”, “Reminisce” and “Mbebe”."]),
 ("03", "img/drop1-fike.jpg", "How to Quit Smoking", "Dominic Fike", "Album · out Friday 30 October", [
   "Dominic Fike's third studio album arrives today. He's also heading to Europe on tour in February 2027, with dates including Berlin and Hamburg."]),
 ("04", "img/drop1-sampa.jpg", "Nu Zamrock", "Sampa the Great", "Album · out Friday 30 October", [
   "The Zambian rapper goes back to Zamrock, the rock sound that came out of Zambia in the 1970s, and pulls it into the present. The album is out on Loma Vista and executive produced by her long-time collaborator Cadenza.",
   "It includes “Simon Says”, which came with a short prelude film, and “Can't Hold Us” with her sister Mwanjé."]),
 ("05", "img/drop1-blxckie.jpg", "YENA", "Blxckie", "Album · out Friday 30 October", [
   "The South African rapper's second album is 15 tracks long and lands five years after his debut, <em>B4Now</em>."]),
 ("06", "img/drop1-kirk.jpg", "I Am What I Am", "Kirk Franklin", "Album · out Friday 30 October", [
   "The gospel giant's new album includes “This Time”, which reunites him with GloRilla."]),
 ("07", "img/drop1-bigx.jpg", "Better Over Time", "BigXthaPlug", "Album · out Friday 30 October", [
   "Eighteen tracks from the Texas rapper, previewed by “LITE” with Belly Gang Kushington."]),
 ("08", "img/drop1-nb.jpg", "Everything Under the Sun", "Nickelback", "Album · out Friday 30 October", [
   "Nickelback's new album is out on Virgin Music Group, led by “Rattle the Cage” featuring guitarist John 5."]),
 ("09", "img/drop1-qotsa.jpg", "Perfecth", "Queens of the Stone Age", "Album · out Friday 30 October", [
   "The rock heavyweights' ninth studio album, featuring the single “Insignificant Other”."]),
]),
("h2", "Also out this week", "The ", "singles"),
("p", "<b>Gracie Abrams, “Here You Come, There You Go”</b> (Thursday 29 October). A new song ahead of <em>Daughter From Hell (Deluxe)</em>, out 20 November, and her <em>SNL</em> return on 31 October."),
("p", "<b>Justice and Gesaffelstein, “Pusher”</b> (Thursday 29 October). The French duo's first track with Gesaffelstein, from Justice's score for <em>Grand Theft Auto VI</em>."),
("p", "<b>Coi Leray featuring Lucky Daye, “Milk N Cookies”</b> (Friday 30 October). From Epic's holiday compilation <em>Holiday Radio</em>."),
("p", "<b>Sam Smith and Jacob Lusk, “My Guy”</b> (Friday 30 October). A new version of Sam Smith's June single."),
]

